import java.util.Scanner;

public class Variant3 {
    static final int MOD = 998244353;
    static long[] factorial;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long pk = sc.nextLong();

        if (pk > N - 1) {
            System.out.println(0);
        } else {
            int k = (int) pk;
            factorial = new long[N + 1];
            factorial[0] = 1;
            for (int i = 1; i <= N; i++) {
                factorial[i] = (factorial[i - 1] * i) % MOD;
            }
            long result = 0;
            int direction = 1;
            int c = N - k;
            for (int i = c; i >= 0; i--) {
                long temp = (choose(c, i) * power(i, N)) % MOD;
                temp *= direction;
                result = (result + temp + MOD) % MOD;
                direction = -direction;
            }
            result = (result * choose(N, c)) % MOD;
            if (k > 0) {
                result = (2 * result) % MOD;
            }
            System.out.println(result);
        }
        sc.close();
    }

    static long choose(int a, int b) {
        long res = (factorial[a] * inv((factorial[b] * factorial[a - b]) % MOD)) % MOD;
        return res;
    }

    static long power(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long inv(long a) {
        return power(a, MOD - 2);
    }
}
